import React, { useState, useEffect, useRef, useCallback } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import RecordRTC from 'recordrtc';
import './CreateCharacter.css';

const CreateCharacter = () => {
  const [overlayVisible, setOverlayVisible] = useState(true);
  const canvasContainerRef = useRef(null);
  const overlayRef = useRef(null);
  const canvasRef = useRef(null);
  const rendererRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const clockRef = useRef(new THREE.Clock());
  const [isPlaying, setIsPlaying] = useState(false);
  const [loadingStatus, setLoadingStatus] = useState('Loading...');
  const [error, setError] = useState(null);
  const modelsRef = useRef([]);
  let controls;

  // Overlay click handler to close the overlay
  const handleOverlayClick = () => {
    setOverlayVisible(false);
  };

  useEffect(() => {
    init();
    animate();

    const overlayElement = overlayRef.current;
    if (overlayElement) {
      overlayElement.addEventListener('click', handleOverlayClick);
    }

    return () => {
      if (overlayElement) {
        overlayElement.removeEventListener('click', handleOverlayClick);
      }
      window.removeEventListener('resize', onWindowResize);
    };
  }, []);

  const init = () => {
    sceneRef.current = new THREE.Scene();
    sceneRef.current.background = new THREE.Color(0x777777);

    cameraRef.current = new THREE.PerspectiveCamera(75, 393 / 800, 0.1, 1000);
    cameraRef.current.position.set(0, 2, 5);

    rendererRef.current = new THREE.WebGLRenderer({ antialias: true, canvas: canvasRef.current });
    rendererRef.current.setPixelRatio(window.devicePixelRatio);
    rendererRef.current.setSize(393, 800);
    canvasContainerRef.current.appendChild(rendererRef.current.domElement);

    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    sceneRef.current.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(2, 2, 2);
    sceneRef.current.add(directionalLight);

    loadModel('/static/models/danceone.glb', () => {
      setLoadingStatus('Loaded Successfully');
    });

    controls = new OrbitControls(cameraRef.current, rendererRef.current.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.25;
    controls.screenSpacePanning = false;
    controls.maxPolarAngle = Math.PI / 2;

    window.addEventListener('resize', onWindowResize, false);
  };

  const loadModel = useCallback((modelPath, onLoad) => {
    const loader = new GLTFLoader();

    loader.load(
      modelPath,
      (gltf) => {
        const model = gltf.scene;
        sceneRef.current.add(model);

        const mixer = new THREE.AnimationMixer(model);
        let action = null;

        if (gltf.animations.length > 0) {
          action = mixer.clipAction(gltf.animations[0]);
          action.setLoop(THREE.LoopRepeat);
          action.clampWhenFinished = true;
          action.paused = true;
        }

        modelsRef.current.push({ model, mixer, action });
        updateCameraView();

        if (onLoad) onLoad();
        setLoadingStatus('Loaded Successfully');
      },
      (xhr) => {
        if (xhr.lengthComputable) {
          const percentComplete = (xhr.loaded / xhr.total) * 100;
          setLoadingStatus(`${Math.round(percentComplete)}% loaded`);
        }
      },
      (error) => {
        console.error('Error loading GLB file:', error);
        setError(`Failed to load model: ${error.message}`);
        setLoadingStatus('Load Failed');
      }
    );
  }, [updateCameraView]);

  const updateCameraView = useCallback(() => {
    if (modelsRef.current.length === 0) return;

    const box = new THREE.Box3();
    modelsRef.current.forEach(({ model }) => {
      box.expandByObject(model);
    });

    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());

    const maxDim = Math.max(size.x, size.y, size.z);
    const fov = cameraRef.current.fov * (Math.PI / 180);
    let cameraZ = Math.abs(maxDim / 2 / Math.tan(fov / 2));
    cameraZ *= 1.5;

    cameraRef.current.position.set(center.x, center.y, center.z + cameraZ);
    cameraRef.current.lookAt(center);
    cameraRef.current.updateProjectionMatrix();
  }, []);

  const playAnimation = () => {
    const newIsPlaying = !isPlaying;
    setIsPlaying(newIsPlaying);
    modelsRef.current.forEach(({ action }) => {
      if (action) {
        action.paused = !newIsPlaying;
        if (newIsPlaying) {
          action.play();
        } else {
          action.stop();
        }
      }
    });
  };

  const animate = () => {
    requestAnimationFrame(animate);

    const delta = clockRef.current.getDelta();
    modelsRef.current.forEach(({ mixer }) => mixer.update(delta));

    controls.update();
    rendererRef.current.render(sceneRef.current, cameraRef.current);
  };

  const onWindowResize = () => {
    cameraRef.current.aspect = window.innerWidth / window.innerHeight;
    cameraRef.current.updateProjectionMatrix();
    rendererRef.current.setSize(window.innerWidth, window.innerHeight);
  };

  const loadAndApplyHat = (hatPath) => {
    const loader = new GLTFLoader();
    if (modelsRef.current.currentHat) {
      modelsRef.current.currentHat.parent.remove(modelsRef.current.currentHat);
      modelsRef.current.currentHat = null;
    }

    loader.load(hatPath, (gltf) => {
      const currentHat = gltf.scene;
      currentHat.position.set(0, -5.1, -0.2);

      const headBone = modelsRef.current[0]?.model?.getObjectByName('mixamorigHead');
      if (headBone) {
        headBone.add(currentHat);
      } else {
        modelsRef.current[0]?.model?.add(currentHat);
      }

      modelsRef.current.currentHat = currentHat;
    }, undefined, (error) => {
      console.error('Error loading hat model:', error);
    });
  };

  const startRecording = async () => {
    const canvas = rendererRef.current.domElement;
    let recorder;

    if (!canvas.captureStream && !canvas.mozCaptureStream) {
      console.error('Canvas capture is not supported on this browser.');
      return;
    }

    rendererRef.current.setSize(360, 640);

    const stream = canvas.captureStream ? canvas.captureStream(30) : canvas.mozCaptureStream(30);
    recorder = new RecordRTC(stream, {
      type: 'video',
      mimeType: 'video/mp4',
      bitsPerSecond: 800000,
    });

    recorder.startRecording();
    playAnimation();

    setTimeout(async () => {
      recorder.stopRecording(async function () {
        let blob = recorder.getBlob();
        const file = new File([blob], 'animation.mp4', { type: 'video/mp4' });

        const comment = prompt('Enter your comment:');
        const formData = new FormData();
        formData.append('file', file);

        try {
          const response = await fetch('/upload', {
            method: 'POST',
            body: formData,
          });
          if (!response.ok) {
            throw new Error('Failed to upload video');
          }
          const data = await response.json();

          const commentData = {
            video_name: data.filename,
            comment: comment,
            datetime: new Date().toISOString(),
          };
          const commentResponse = await fetch('/comment', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(commentData),
          });
          if (!commentResponse.ok) {
            throw new Error('Failed to upload comment');
          }
        } catch (error) {
          console.error('Error during upload:', error);
        }
      });
    }, 5000);
  };

  const handleBackgroundUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = function (e) {
        const texture = new THREE.TextureLoader().load(e.target.result);
        sceneRef.current.background = texture;
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div style={{ overflow: 'auto' }}>
      {overlayVisible && (
        <div id="overlay" className="overlay" ref={overlayRef}>
          <div className="overlay-content">
            <img
              src="../static/stockimages/make_invitation.png"
              alt="Invitation"
            />
            <div className="text-overlay">
              <span id="top">
                우리가 만든 춤판,<br />
                만들 새바람
              </span>

              <span id="middle">
                To. 모든 여러분들<br /><br />
                정신 없고 복잡한 세상 속에서 안녕하셨나요?<br />
                꽉 찬 달처럼, 세상을 한 번 뒤집을 때가 무르익었어요!<br />
                ‘우리’들의 댄스타임에 초대합니다!<br />
                각자가 원하는 모습으로 함께 춤을 추어요!<br />
                10월 중반. 바람이 부는 날 생명 평화의 나무 밑에서 만나요.<br />
                우리들만의 약속입니다!
              </span>

              <span id="bottom">
                김화순 개인전 : 전시 제목 블라블라 라고 합니다.<br />
                일시 : 2024. 10. 12. - 10. 29.<br />
                위치 : 자하미술관
              </span>
            </div>
          </div>
        </div>
      )}

      <header>
        <div className="titleArea">
          <div>
            <img
              src="/static/icons/back_double.png"
              alt="back"
              id="back-button"
              onClick={() => window.history.back()}
            />
          </div>
          <div style={{ fontSize: '20px', color: '#412823' }}>춤 함께 추기</div>
          <div></div>
        </div>
      </header>

      <div id="container" style={{ display: 'flex', flexDirection: 'column', marginTop: '58px', height: '100vh' }}>
        <div id="canvasContainer" ref={canvasContainerRef} style={{ zIndex: 10, position: 'fixed' }}>
          <canvas ref={canvasRef} style={{ width: '393px', height: '800px' }} />
        </div>

        <div className="controls">
          <div className="color-selection">
            <button style={{ backgroundColor: '#ff0000' }}></button>
            <button style={{ backgroundColor: '#00ff00' }}></button>
            <button style={{ backgroundColor: '#0000ff' }}></button>
            <button style={{ backgroundColor: '#ffff00' }}></button>
            <button style={{ backgroundColor: '#ff00ff' }}></button>
            <button style={{ backgroundColor: '#00ffff' }}></button>
            <button style={{ backgroundColor: '#ff9900' }}></button>
            <button style={{ backgroundColor: '#99ff00' }}></button>
          </div>

          <div className="asset-grid">
            <img src="https://placehold.co/200x200" alt="Asset 1" />
            <img src="https://placehold.co/200x200" alt="Asset 2" />
            <img src="https://placehold.co/200x200" alt="Asset 3" />
            <img src="https://placehold.co/200x200" alt="Asset 4" />
            <img src="https://placehold.co/200x200" alt="Asset 5" />
            <img src="https://placehold.co/200x200" alt="Asset 6" />
            <img src="https://placehold.co/200x200" alt="Asset 7" />
            <img src="https://placehold.co/200x200" alt="Asset 8" />
            <img src="https://placehold.co/200x200" alt="Asset 9" />
            <img src="https://placehold.co/200x200" alt="Asset 10" />
          </div>

          <div id="bottombuttons">
            <div className="category-selection">
              <button onClick={() => loadAndApplyHat('static/models/box_profile_metal_sheet_4k.glb')}>hat1</button>
              <button onClick={() => loadAndApplyHat('static/models/danceone.glb')}>hat2</button>
              <button onClick={playAnimation}>animate</button>
              <button>dd</button>
              <button>소품</button>
              <button>얼굴</button>
            </div>

            <button className="create-character" id="saveButton" onClick={startRecording}>
              캐릭터 생성하기
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreateCharacter;
